bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    if (!record->event.pressed) {
        return true;
    }
    switch (keycode) {
    case CLEAR_LAYER:
        layer_clear();
        layer_on(BASE);
        return false;
    case LAYER_DOWN:
    case LAYER_UP:
        uint8_t current_layer = get_highest_layer(layer_state);
        layer_clear();
        if (keycode == LAYER_UP) {
            if (current_layer < MIN_LAYERS || current_layer >= MAX_LAYERS) {
                layer_on(MIN_LAYERS);
                return false;
            }
            layer_on(current_layer + 1);
            return false;
        }
        if (current_layer <= MIN_LAYERS || current_layer > MAX_LAYERS) {
            layer_on(MAX_LAYERS);
            return false;
        }
        layer_on(current_layer - 1);
        return false;
    case V_WORD:
        SEND_STRING(SS_LCTL(SS_TAP(X_LEFT)));
        SEND_STRING(SS_LCTL(SS_LSFT(SS_TAP(X_RGHT))));
        return false;
    case V_LINE:
        SEND_STRING(SS_LCTL(SS_TAP(X_HOME)));
        SEND_STRING(SS_LCTL(SS_LSFT(SS_TAP(X_END))));
        return false;
    case LAYER_4:
        layer_clear();
        layer_on(4);
        return false;
    case LAYER_5:
        layer_clear();
        layer_on(5);
        return false;
    case LAYER_6:
        layer_clear();
        layer_on(6);
        return false;
    case LAYER_7:
        layer_clear();
        layer_on(7);
        return false;
    case LAYER_8:
        layer_clear();
        layer_on(8);
        return false;
    }

    return true;
}

