void keyboard_post_init_user(void) {
    ap2_led_enable();
    ap2_led_set_profile(3);
}

void update_led_colors(void) {
    ap2_led_reset_foreground_color();
    const ap2_led_t color_yellow = {.p.red = 0xff, .p.green = 0xff, .p.blue = 0x00, .p.alpha = 0xff};
    const ap2_led_t color_red    = {.p.red = 0xff, .p.green = 0x00, .p.blue = 0x00, .p.alpha = 0xff};
    // Set number key to yellow
    for (size_t col = 1; col < 13; col++) {
        ap2_led_colors_set_key(0, col, color_yellow);
    }
    for (size_t col = 1; col < 13; col++) {
        ap2_led_colors_set_key(1, col, color_red);
    }
    for (size_t col = 1; col < 12; col++) {
        ap2_led_colors_set_key(2, col, color_red);
    }
    for (size_t col = 1; col < 11; col++) {
        ap2_led_colors_set_key(3, col, color_red);
    }
}

layer_state_t layer_state_set_user(layer_state_t state) {
    switch (get_highest_layer(state)) {
    // case BASE:
    //     update_led_colors();
    //     break;
    case FN3:
        ap2_led_set_foreground_color(0xFF, 0x00, 0x00);
        break;
    case FN4:
        ap2_led_set_foreground_color(0xFF, 0x80, 0x00);
        break;
    case FN5:
        ap2_led_set_foreground_color(0xFF, 0xFF, 0x00);
        break;
    case FN6:
        ap2_led_set_foreground_color(0x80, 0xFF, 0x00);
        break;
    case FN7:
        ap2_led_set_foreground_color(0x00, 0xFF, 0x00);
        break;
    case FN8:
        ap2_led_set_foreground_color(0x00, 0xFF, 0xFF);
        break;
    case FN9:
        ap2_led_set_foreground_color(0x00, 0x00, 0xFF);
        break;
    case FN10:
        ap2_led_set_foreground_color(0x80, 0x00, 0xFF);
        break;
    default:
        // Reset back to the current profile
        ap2_led_reset_foreground_color();
        break;
    }
    return state;
}

// The function to handle the caps lock logic
// It's called after the capslock changes state or after entering layers 1 and 2.
bool led_update_user(led_t leds) {
    if (leds.caps_lock) {
        // Set the caps-lock to red
        const ap2_led_t color = {.p.red = 0xff, .p.green = 0x00, .p.blue = 0x00, .p.alpha = 0xff};
        ap2_led_sticky_set_key(2, 0, color);
        /* NOTE: Instead of colouring the capslock only, you can change the whole
           keyboard with ap2_led_mask_set_mono */
    } else {
        // Reset the capslock if there is no layer active
        ap2_led_unset_sticky_key(2, 0);
    }

    return true;
}

